import React, { useState, useEffect, useCallback } from "react";

// ————————————————————————————————————————————————————————————————
// <PayByLeapCardDeck />
// Drop-in animated "Stablecoin Cards" feature card: your real GBP /
// NGN / USD card art in an auto-shuffling deck — front card tucks to
// the back on a timer, hovering fans the stack so all three are
// readable, clicking any card brings it to the front, and a quiet
// sheen sweeps the front card. Transparent background.
//
// Usage:
//   import PayByLeapCardDeck from "./PayByLeapCardDeck";
//   <PayByLeapCardDeck />
//
// Props (all optional):
//   background   — section background color   (default "#FBF1D8")
//   minHeight    — section min-height in px    (default 730)
//   autoPlay     — auto-shuffle the deck       (default true)
//   className / style — passed to the root <section>
// ————————————————————————————————————————————————————————————————

//const MAROON = "#9B1414";
const INK = "#141110";
const EASE = "cubic-bezier(.16,.8,.26,1)";

const IMG = {
  cardGBP:
    "data:image/webp;base64,",
  cardNGN:
    "data:image/webp;base64,",
  cardUSD:
    "data:image/webp;base64,",
};

type CardId = "GBP" | "NGN" | "USD";
type CardImgKey = keyof typeof IMG;

interface OverlayPatch {
  bg: string; // sampled card background color, to patch over the baked-in text
  last4: { text: string; left: number; top: number; w: number; h: number };
  name: { text: string; left: number; top: number; w: number; h: number };
}

interface CardDef {
  id: CardId;
  img: CardImgKey;
  shadow: string;
  /** Patches the baked-in number/name so this card reads as a distinct
   * account — the source image itself is never modified. Omit for a
   * card that should show exactly what's in its image. */
  overlay?: OverlayPatch;
}

const DECK: CardDef[] = [
  {
    id: "GBP",
    img: "cardGBP",
    shadow: "rgba(190,140,30,.4)",
    overlay: {
      bg: "#D19C19", // sampled card background
      last4: { text: "9231", left: 36.5, top: 9.6, w: 10.5, h: 6.2 },
      name: { text: "SOPHIA BENSON", left: 5.8, top: 81.6, w: 40, h: 6.5 },
    },
  },
  { id: "NGN", img: "cardNGN", shadow: "rgba(0,0,0,.45)" },
  { id: "USD", img: "cardUSD", shadow: "rgba(140,18,18,.4)" },
];

export interface PayByLeapCardDeckProps {
  /** deck footprint width in px */
  width?: number | string;
  /** deck footprint height in px — fanned cards need room to spread */
  height?: number | string;
  autoPlay?: boolean;
  className?: string;
  style?: React.CSSProperties;
}

export default function PayByLeapCardDeck({
  width = 460,
  height = 560,
  autoPlay = true,
  className = "",
  style = {},
}: PayByLeapCardDeckProps) {
  const [order, setOrder] = useState<CardId[]>(["GBP", "NGN", "USD"]); // last = front
  const [leaving, setLeaving] = useState<CardId | null>(null);
  const [fanned, setFanned] = useState(false);
  const [manualUntil, setManualUntil] = useState(0);

  useEffect(() => {
    if (!autoPlay || fanned) return;
    const wait = Math.max(4600, manualUntil - Date.now());
    const t = setTimeout(() => {
      const front = order[order.length - 1];
      setLeaving(front);
      setTimeout(() => {
        setOrder((o) => [o[o.length - 1], ...o.slice(0, -1)]);
        setLeaving(null);
      }, 620);
    }, wait);
    return () => clearTimeout(t);
  }, [order, fanned, manualUntil, autoPlay]);

  const bringToFront = useCallback((id: CardId) => {
    setOrder((o) => [...o.filter((c) => c !== id), id]);
    setManualUntil(Date.now() + 9000);
  }, []);

  return (
    <div className={className} style={{ ...styles.root, width, height, ...style }}>
      <style>{css}</style>

      <div
        style={{ ...styles.deckArea, width: "100%", height: "100%" }}
        onMouseEnter={() => setFanned(true)}
        onMouseLeave={() => setFanned(false)}
      >
        {order.map((id, idx) => {
          const card = DECK.find((c) => c.id === id)!;
          const gap = fanned ? 45 : 32;
          const isFront = idx === order.length - 1 && !leaving;
          const isLeaving = leaving === id;
          return (
            <div
              key={id}
              onClick={() => bringToFront(id)}
              className={isFront ? "pbl-card-sheen" : ""}
              style={{
                ...styles.cardSlot,
                zIndex: idx + 1,
                filter: `drop-shadow(0 ${14 + idx * 8}px ${26 + idx * 8}px ${card.shadow})`,
                transform: isLeaving
                  ? `translateY(calc(${idx * gap}% + 15%)) translateX(15%) rotate(4.5deg) scale(.985)`
                  : `translateY(${idx * gap}%) rotate(${fanned ? (idx - 1) * 1.4 : 0}deg)`,
                opacity: isLeaving ? 0.3 : 1,
              }}
            >
              <img
                src={IMG[card.img]}
                alt={`PayByLeap ${id} card`}
                style={{ width: "100%", display: "block" }}
                draggable={false}
              />
              {card.overlay && (
                <>
                  <div
                    style={{
                      position: "absolute",
                      left: `${card.overlay.last4.left}%`,
                      top: `${card.overlay.last4.top}%`,
                      width: `${card.overlay.last4.w}%`,
                      height: `${card.overlay.last4.h}%`,
                      background: card.overlay.bg,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "flex-end",
                    }}
                  >
                    <span style={styles.overlayNumber}>
                      {card.overlay.last4.text}
                    </span>
                  </div>
                  <div
                    style={{
                      position: "absolute",
                      left: `${card.overlay.name.left}%`,
                      top: `${card.overlay.name.top}%`,
                      width: `${card.overlay.name.w}%`,
                      height: `${card.overlay.name.h}%`,
                      background: card.overlay.bg,
                      display: "flex",
                      alignItems: "center",
                    }}
                  >
                    <span style={styles.overlayName}>
                      {card.overlay.name.text}
                    </span>
                  </div>
                </>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ————————————————— styles —————————————————

const styles: Record<string, React.CSSProperties> = {
  // transparent, self-contained footprint — no heading/copy/link,
  // sits directly on YOUR background
  root: {
    position: "relative",
    fontFamily:
      "'Avenir Next','Nunito Sans','Segoe UI',system-ui,-apple-system,sans-serif",
    color: INK,
  },
  deckArea: {
    position: "relative",
    cursor: "pointer",
  },
  cardSlot: {
    position: "absolute",
    left: 0,
    right: 0,
    borderRadius: 26,
    overflow: "hidden",
    transition: `transform .8s ${EASE}, opacity .55s ${EASE}, filter .8s ${EASE}`,
    containerType: "inline-size",
  } as React.CSSProperties,
  overlayNumber: {
    fontSize: "4.1cqw",
    fontWeight: 500,
    color: "#fff",
    letterSpacing: "0.03em",
    whiteSpace: "nowrap",
  } as React.CSSProperties,
  overlayName: {
    fontSize: "4.6cqw",
    fontWeight: 500,
    color: "#fff",
    letterSpacing: "0.02em",
    whiteSpace: "nowrap",
  } as React.CSSProperties,
};

const css = `
  .pbl-card-sheen::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(115deg, transparent 35%, rgba(255,255,255,.16) 50%, transparent 65%);
    transform: translateX(-130%);
    animation: pblSheen 4.6s ${EASE} infinite;
    pointer-events: none;
  }
  @keyframes pblSheen {
    0% { transform: translateX(-130%); }
    38% { transform: translateX(130%); }
    100% { transform: translateX(130%); }
  }

  @media (prefers-reduced-motion: reduce) {
    .pbl-card-sheen::after { animation: none !important; }
  }
`;
